import { spawnSync } from "node:child_process";
import { existsSync, readFileSync, renameSync, rmSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { transformSync } from "esbuild";
import { appRuntimePaths } from "./runtime-manifest.mjs";
import { lazyStyleBundles, styleLayerOrder, styleRuntimePaths } from "./style-manifest.mjs";
import { generateBuildInfo } from "./lib/build-info.mjs";
import {
  bundleCacheHit,
  bundleInputsDigest,
  markBundleBuilt,
} from "./lib/incremental-bundle.mjs";
import { minifyCss } from "./lib/minify-css.mjs";
import { desktopRoot, repositoryRoot } from "./lib/paths.mjs";
import { patchTesseractWorker } from "./patch-tesseract-worker.mjs";

const root = repositoryRoot;

// Regenerate the single source of version/build/commit and stamp the
// index.html cache-busters before the bundle is assembled, so every build
// path (dev, verify:release, web release, packaging) reports one identity.
const buildIdentity = generateBuildInfo();

// pkg needs the explicit worker entrypoint. The versioned patch verifies both
// dependency version and source hash, and fails the build on any drift.
patchTesseractWorker(root);
const cssBundlePath = "styles.bundle.css";

// Three kinds of output, three digests. They used to share one: editing one
// application's lazy stylesheet re-ran the JS minification (about 1.7 MB of
// concatenated classic scripts) and rewrote every other sheet byte-for-byte.
// Each part now answers for itself — byte-identical inputs and an intact
// output mean that part is skipped, and a change to one part cannot make
// another part's build decision. Every file that reaches a part, the build
// identity and the bundler version are in that part's digest, so a source
// change always rebuilds the part it belongs to.
const sharedInputs = [
  fileURLToPath(import.meta.url),
  join(root, "tooling", "patch-tesseract-worker.mjs"),
  join(root, "tooling", "lib", "minify-css.mjs"),
  join(root, "tooling", "runtime-manifest.mjs"),
  join(root, "tooling", "style-manifest.mjs"),
  join(root, "node_modules", "esbuild", "package.json"),
];
const cacheExtras = [
  JSON.stringify(buildIdentity),
  process.env.AI_SYSTEM6_SOURCE_COMMIT || "",
];
const appBundlePath = join(desktopRoot, "app.bundle.js");
const cssBundleOutputPath = join(desktopRoot, cssBundlePath);
const jsDigest = bundleInputsDigest([
  ...appRuntimePaths.map((path) => join(desktopRoot, path)),
  ...sharedInputs,
], cacheExtras);
const cssDigest = bundleInputsDigest([
  ...styleRuntimePaths.map((path) => join(desktopRoot, path)),
  ...sharedInputs,
], cacheExtras);
const lazyParts = lazyStyleBundles.map((bundle) => ({
  bundle,
  output: join(desktopRoot, bundle.output),
  digest: bundleInputsDigest([
    ...bundle.sources.map((path) => join(desktopRoot, path)),
    ...sharedInputs,
  ], cacheExtras),
}));
const jsCached = bundleCacheHit("app-js", jsDigest) && existsSync(appBundlePath);
const cssCached = bundleCacheHit("app-css", cssDigest) && existsSync(cssBundleOutputPath);
lazyParts.forEach((part) => {
  part.cached = bundleCacheHit(`lazy-css-${part.bundle.id}`, part.digest) && existsSync(part.output);
});

const banner = [
  "// Generated by tooling/build-app-bundle.mjs.",
  "// Keep source edits in app/ modules or app.js, then run npm run build:app.",
  "",
].join("\n");

function stripJsSourceMapComments(source) {
  return source.replace(/(?:^|\n)\/\/# sourceMappingURL=.*(?:\n|$)/g, "\n").trimEnd();
}

if (!jsCached) {
  // Kept as parts as well as text: when a source file does not parse, the
  // bundler reports a line number in the concatenated body, and the marker each
  // file writes above itself is what turns that number back into a file name.
  let bodyLine = 1;
  const bodyParts = [];
  const sourceLineIndex = [];
  for (const path of appRuntimePaths) {
    const text = stripJsSourceMapComments(readFileSync(join(desktopRoot, path), "utf8"));
    sourceLineIndex.push({ path, line: bodyLine });
    bodyParts.push([`// ===== ${path} =====`, text, ""].join("\n"));
    bodyLine += 2 + text.split("\n").length;
  }
  const body = bodyParts.join("\n");
  const sourceFileForLine = (line) => {
    let found = "";
    for (const entry of sourceLineIndex) {
      if (entry.line <= line) found = entry.path;
      else break;
    }
    return found;
  };

// esbuild's minifyWhitespace already strips leading whitespace, and
// legalComments:"none" drops the inline section markers, so the bundle is fed
// to it directly. A hand-rolled pre-pass used to compact leading whitespace
// here; it was removed because it was not a real tokenizer — it misread some
// `/` as regex starts and swallowed text up to the next `/`, which could land
// inside a string such as "https://…" and corrupt the bundle. It contributed
// nothing to the output, and the damage only stayed invisible while the
// miscounts happened to cancel between files: moving one file out of the
// bundle was enough to break the build.
  let minifiedBody;
  try {
    minifiedBody = transformSync(body, {
      charset: "utf8",
      legalComments: "none",
      loader: "js",
      // Identifier minification must stay off: the bundle is concatenated scripts
      // whose top-level declarations are the shared global namespace, and lazy
      // modules loaded later call those globals by name. Syntax minification is
      // safe — it drops none of the 2,348 top-level declarations.
      minifyIdentifiers: false,
      minifySyntax: true,
      minifyWhitespace: true,
      target: "esnext",
    }).code.trim();
  } catch (error) {
    // A typo in one module used to end the build as an esbuild stack trace with
    // a line number into the concatenated body — the least useful form of the
    // most common failure. Keep esbuild's own words, and say where in the
    // concatenation it gave up: the parser runs on past the broken module and
    // complains about the first token it cannot continue with, so the module
    // named here is the one just AFTER the usual suspect.
    const message = String(error?.message || error).split("\n").slice(0, 3).join("\n");
    const at = /:(\d+):(\d+):/.exec(error?.message || "");
    const file = at ? sourceFileForLine(Number(at[1])) : "";
    console.error("app.bundle.js was not replaced: the boot sources do not parse.");
    console.error(message);
    if (file) {
      console.error(`Line ${at[1]} falls in ${file}; the mistake is usually in the module just above it.`);
    }
    process.exit(1);
  }
  // Keep the source inventory for debugging without paying one repeated comment
  // prefix per module in the public boot bundle.
  const sourceSectionManifest = `// Sources: ${appRuntimePaths.join(",")}`;
  // Check the bytes before they replace the served bundle. Writing first and
  // checking afterwards left a syntactically broken app.bundle.js in the tree
  // whenever a source edit did not parse — during `npm run dev` that is the
  // file the browser is being served.
  // The staging name keeps the .js extension: `node --check` refuses to read a
  // file whose extension it does not know, which would fail every build.
  const stagedBundlePath = `${appBundlePath}.${process.pid}.staged.js`;
  writeFileSync(stagedBundlePath, `${banner}${sourceSectionManifest}\n${minifiedBody}\n`, "utf8");
  const syntaxCheck = spawnSync(process.execPath, ["--check", stagedBundlePath], {
    cwd: desktopRoot,
    encoding: "utf8",
  });
  if (syntaxCheck.status !== 0) {
    rmSync(stagedBundlePath, { force: true });
    console.error(syntaxCheck.stderr || syntaxCheck.stdout);
    console.error("app.bundle.js was not replaced: the previous build is still the last good one.");
    process.exit(syntaxCheck.status || 1);
  }
  renameSync(stagedBundlePath, appBundlePath);

  markBundleBuilt("app-js", jsDigest);
  console.log(`Built app.bundle.js from ${appRuntimePaths.length} source files.`);
} else {
  console.log("app.bundle.js unchanged (cached).");
}

// The @layer statement pins the cascade-layer order for the whole document
// (lazy sheets included) before any rule loads. It is inert for rules that are
// not wrapped in a layer, so emitting it ahead of the migration is safe; the
// order itself is single-sourced in style-manifest.mjs.
const layerPreamble = `@layer ${styleLayerOrder.join(", ")};\n`;

// The origin serves non-HTML/JS/CSS assets with a bounded cache lifetime
// (public, max-age=86400) and the CSS refers to them by stable URLs, so a
// release that changes an asset would leave returning visitors on the old
// bytes for up to a day. index.html already busts its own bundle refs with
// ?v=<build>; stamp every static asset url() in the CSS bundle with the same
// build so a new release always fetches fresh icons, sprites and fonts.
function stampCssAssetUrls(css, build) {
  return css.replace(
    /url\(\s*(['"]?)((?:\.{0,2}\/)*assets\/[\w./-]+\.(?:svg|png|jpg|jpeg|webp|gif|ico|woff|woff2|dat|ttf)(?:\?[^)'"]*)?)\1\s*\)/gi,
    (match, quote, url) => (/\?/.test(url) ? match : `url(${quote}${url}?v=${build}${quote})`)
  );
}

if (!cssCached) {
  const cssSource = layerPreamble + styleRuntimePaths
    .map((path) => readFileSync(join(desktopRoot, path), "utf8"))
    .join("\n");
  const cssBundle = stampCssAssetUrls(minifyCss(cssSource), buildIdentity.build);
  writeFileSync(cssBundleOutputPath, `${cssBundle}\n`, "utf8");
  markBundleBuilt("app-css", cssDigest);
  console.log(`Built ${cssBundlePath} from ${styleRuntimePaths.length} source files.`);
} else {
  console.log(`${cssBundlePath} unchanged (cached).`);
}

// Lazy stylesheets are built the same way, just into their own files. They are
// requested by the window that needs them, so they never enter a boot.
for (const part of lazyParts) {
  if (part.cached) {
    console.log(`${part.bundle.output} unchanged (cached).`);
    continue;
  }
  const source = part.bundle.sources.map((path) => readFileSync(join(desktopRoot, path), "utf8")).join("\n");
  const built = stampCssAssetUrls(minifyCss(source), buildIdentity.build);
  writeFileSync(part.output, `${built}\n`, "utf8");
  markBundleBuilt(`lazy-css-${part.bundle.id}`, part.digest);
  console.log(`Built ${part.bundle.output} from ${part.bundle.sources.length} source file(s), loaded on demand.`);
}
